//
// Uniform contract Error bodies (T031): {code, message, correlation_id[, details]}. The
// message is a fixed generic sentence per code and never echoes request content; the
// correlation ID is generated by the server for every request (a client-supplied value is
// never used) and is also sent as X-Correlation-Id.

import { randomBytes } from 'node:crypto';

import type { ErrorCode, ErrorDetail } from './types.ts';

const MESSAGES: Readonly<Record<ErrorCode, string>> = {
  invalid_request: 'The request is not valid.',
  unauthenticated: 'Authentication is required.',
  forbidden: 'The request is not allowed.',
  not_found: 'The resource was not found.',
  version_conflict: 'The expected version does not match.',
  state_conflict: 'The resource state does not allow this request.',
  order_conflict: 'Another recipient must act first.',
  idempotency_conflict: 'The idempotency key was used with a different request.',
  confirmation_required: 'A human operator confirmation is required.',
  confirmation_invalid: 'The confirmation is not valid for this request.',
  not_completed: 'The envelope is not completed.',
  payload_too_large: 'The request body is too large.',
  unsupported_media_type: 'The request media type is not supported.',
  unsupported_pdf: 'The document is not a supported PDF.',
  field_out_of_bounds: 'A field lies outside its page.',
  unsupported_characters: 'The text contains unsupported characters.',
  rate_limited: 'Too many requests.',
  locked: 'The request is locked.',
  csrf_failed: 'The request could not be verified.',
  origin_rejected: 'The request origin is not allowed.',
  digest_mismatch: 'A digest does not match.',
  consent_mismatch: 'The consent does not match.',
  finalization_not_retryable: 'Finalization cannot be retried now.',
  destination_not_allowed: 'The destination is not allowed.',
  precondition_required: 'A precondition header is required.',
  internal: 'The request could not be completed.',
};

export function newCorrelationId(): string {
  return randomBytes(16).toString('base64url');
}

export function errorBody(code: ErrorCode, correlationId: string, details: readonly ErrorDetail[] = []): Record<string, unknown> {
  const body: Record<string, unknown> = { code, message: MESSAGES[code], correlation_id: correlationId };
  if (details.length > 0) {
    body.details = details.slice(0, 20).map((detail) => ({ field: String(detail.field).slice(0, 100), code: String(detail.code).slice(0, 60) }));
  }
  return body;
}
